 = `hcsyria_financial_test`.`actiontype`.`id`)) left join `hcsyria_financial_test`.`all_avgrates` on(`hcsyria_financial_test`.`action`.`Rate_ID` = `all_avgrates`.`id`)) where `hcsyria_financial_test`.`actiontype`.`shortname` in ('E','Ex') and `hcsyria_financial_test`.`action`.`BudgetLine_ID` = `hcsyria_financial_test`.`budget_line`.`ID` and date_format(`hcsyria_financial_test`.`action`.`ActionDate`,'%m/%Y') = date_format(str_to_date(concat('01/',case when `budget_date__monthes`.`month` < 10 then '0' else '' end,`budget_date__monthes`.`month`,'/',`budget_date__monthes`.`year`),'%d/%m/%Y'),'%m/%Y')) AS `Expenditures`,`hcsyria_financial_test`.`budget`.`BeginDate` AS `budget_BeginDate`,`hcsyria_financial_test`.`budget`.`EndDate` AS `budget_EndDate`,str_to_date(concat('01-',case when `budget_date__monthes`.`month` < 10 then '0' else '' end,`budget_date__monthes`.`month`,'-',`budget_date__monthes`.`year`),'%d-%m-%Y') AS `BudgetMonthes`,(select ifnull(sum(case when `hcsyria_financial_test`.`action`.`currency_tilltype_id` = 2 then `hcsyria_financial_test`.`action`.`Amount` else `hcsyria_financial_test`.`action`.`Amount` / `all_avgrates`.`Value` end),0) from ((`hcsyria_financial_test`.`action` left join `hcsyria_financial_test`.`actiontype` on(`hcsyria_financial_test`.`action`.`AType_ID` = `hcsyria_financial_test`.`actiontype`.`id`)) left join `hcsyria_financial_test`.`all_avgrates` on(`hcsyria_financial_test`.`action`.`Rate_ID` = `all_avgrates`.`id`)) where `hcsyria_financial_test`.`actiontype`.`shortname` in ('E','Ex') and `hcsyria_financial_test`.`action`.`BudgetLine_ID` = `hcsyria_financial_test`.`budget_line`.`ID`) AS `Expenditures_With_Out_Of_Date` from ((((((((((`hcsyria_financial_test`.`budget_line` left join `hcsyria_financial_test`.`budget` on(`hcsyria_financial_test`.`budget_line`.`Budget_ID` = `hcsyria_financial_test`.`budget`.`ID`)) left join `hcsyria_financial_test`.`account` on(`hcsyria_financial_test`.`account`.`ID` = `hcsyria_financial_test`.`budget`.`Account_ID`)) left join `hcsyria_financial_test`.`subproject` on(`hcsyria_financial_test`.`account`.`SubProject_ID` = `hcsyria_financial_test`.`subproject`.`ID`)) left join `hcsyria_financial_test`.`project` on(`hcsyria_financial_test`.`project`.`ID` = `hcsyria_financial_test`.`subproject`.`Project_ID`)) left join `hcsyria_financial_test`.`city` on(`hcsyria_financial_test`.`subproject`.`City_ID` = `hcsyria_financial_test`.`city`.`ID`)) left join `hcsyria_financial_test`.`tilltypes` on(`hcsyria_financial_test`.`budget`.`Budget_Type_ID` = `hcsyria_financial_test`.`tilltypes`.`ID`)) left join `hcsyria_financial_test`.`line` on(`hcsyria_financial_test`.`budget_line`.`Line_ID` = `hcsyria_financial_test`.`line`.`ID`)) left join `hcsyria_financial_test`.`linecategory` on(`hcsyria_financial_test`.`linecategory`.`ID` = `hcsyria_financial_test`.`line`.`Category_ID`)) left join `hcsyria_financial_test`.`linecategorytype` on(`hcsyria_financial_test`.`linecategorytype`.`ID` = `hcsyria_financial_test`.`linecategory`.`Type_ID`)) join `hcsyria_financial_test`.`budget_date__monthes` on(`budget_date__monthes`.`budget_id` = `hcsyria_financial_test`.`budget`.`ID`)) where cast(concat_ws('-',`budget_date__monthes`.`year`,`budget_date__monthes`.`month`,dayofmonth(`hcsyria_financial_test`.`budget`.`BeginDate`)) as date) between cast(`hcsyria_financial_test`.`budget`.`BeginDate` as date) and cast(`hcsyria_financial_test`.`budget`.`EndDate` as date) order by `hcsyria_financial_test`.`budget`.`ID`,`hcsyria_financial_test`.`budget_line`.`ID`,`budget_date__monthes`.`year`,`budget_date__monthes`.`month`
